using System;
using UnityEditor;
using UnityEditor.Events;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.UI;
namespace CatCafePreview.Editor
{
    public static class PythonDispatchComparisonSetup
    {
        static T Copy<T>(T source,Transform root,Transform target) where T:Component{return target.Find(AnimationUtility.CalculateTransformPath(source.transform,root)).GetComponent<T>();}
        static void Place(RectTransform r,float x,float y,float w,float h){r.anchorMin=r.anchorMax=r.pivot=new Vector2(0,1);r.anchoredPosition=new Vector2(x,-y);r.sizeDelta=new Vector2(w,h);}
        static void Bind(Button b,UnityEngine.Events.UnityAction action){b.onClick=new Button.ButtonClickedEvent();UnityEventTools.AddPersistentListener(b.onClick,action);b.onClick.SetPersistentListenerState(0,UnityEngine.Events.UnityEventCallState.EditorAndRuntime);}
        static Dropdown Dropdown(Transform parent,string name,float x,float width,UnityEngine.Events.UnityAction<int> action){var go=DefaultControls.CreateDropdown(new DefaultControls.Resources());go.name=name;go.transform.SetParent(parent,false);Place(go.GetComponent<RectTransform>(),x,78,width,40);var d=go.GetComponent<Dropdown>();foreach(var text in go.GetComponentsInChildren<Text>(true)){text.font=ContentPreviewLayout.LoadFont();text.fontSize=16;}ContentPreviewLayout.ConfigureCatDropdown(d);var arrow=go.transform.Find("Arrow");arrow.GetComponent<Image>().color=Color.clear;var marker=new GameObject("Arrow Label",typeof(RectTransform),typeof(Text));marker.transform.SetParent(arrow,false);var rect=marker.GetComponent<RectTransform>();rect.anchorMin=Vector2.zero;rect.anchorMax=Vector2.one;rect.offsetMin=rect.offsetMax=Vector2.zero;var markerText=marker.GetComponent<Text>();markerText.font=ContentPreviewLayout.LoadFont();markerText.fontSize=14;markerText.text="▼";markerText.color=Color.black;markerText.alignment=TextAnchor.MiddleCenter;markerText.raycastTarget=false;UnityEventTools.AddPersistentListener(d.onValueChanged,action);d.onValueChanged.SetPersistentListenerState(0,UnityEngine.Events.UnityEventCallState.EditorAndRuntime);return d;}
        [MenuItem("Cat Cafe/開発用/UI再生成/猫ごとの派遣先比較",false,40)]
        public static void Build()
        {
            var scene=EditorSceneManager.OpenScene("Assets/Scenes/CatCafePythonState.unity");var preview=UnityEngine.Object.FindObjectOfType<ContentPreview>();var source=preview.GetComponent<PythonObjectiveStartPanel>();var root=source.panel.transform.parent;var old=root.Find("Dispatch Comparison");if(old!=null)UnityEngine.Object.DestroyImmediate(old.gameObject);var p=preview.GetComponent<PythonDispatchComparisonPanel>() ?? preview.gameObject.AddComponent<PythonDispatchComparisonPanel>();p.panel=UnityEngine.Object.Instantiate(source.panel,root);p.panel.name="Dispatch Comparison";var s=source.panel.transform;var t=p.panel.transform;p.title=Copy(source.title,s,t);p.details=Copy(source.details,s,t);p.notice=Copy(source.notice,s,t);p.proceed=Copy(source.proceed,s,t);p.close=Copy(source.close,s,t);foreach(var tab in source.tabs)UnityEngine.Object.DestroyImmediate(Copy(tab,s,t).gameObject);UnityEngine.Object.DestroyImmediate(t.Find(AnimationUtility.CalculateTransformPath(source.confirmation.transform,s)).gameObject);var card=p.close.transform.parent;
            p.cats=Dropdown(card,"Cat",24,280,p.SelectCat);p.destinations=Dropdown(card,"Destination",320,596,p.SelectDestination);var scroll=p.details.GetComponentInParent<ScrollRect>(true);Place(scroll.GetComponent<RectTransform>(),24,130,892,300);Place(scroll.viewport,6,6,862,288);scroll.verticalScrollbar.GetComponent<RectTransform>().sizeDelta=new Vector2(12,288);p.details.fontSize=17;Place(p.notice.rectTransform,24,440,892,98);p.notice.fontSize=14;Bind(p.proceed,p.Proceed);Bind(p.close,p.Close);p.proceed.GetComponentInChildren<Text>().text="選んだ派遣先の画面へ";p.panel.SetActive(false);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);PythonEventListSetup.Build();Debug.Log("CAT_CAFE_DISPATCH_COMPARISON_UI_OK");
        }
        public static void BuildAndVerify()
        {
            Build();var preview=UnityEngine.Object.FindObjectOfType<ContentPreview>();preview.Initialize();var client=preview.GetComponent<PythonStateClient>();var f=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;typeof(PythonStateClient).GetField("preview",f).SetValue(client,preview);var state=PythonServiceSetup.Sample();state.instance_id="comparison-test";var a=state.cats[0].cat_id;var b=state.cats[1].cat_id;
            Func<string,PythonDispatchComparisonCat> cat=id=>new PythonDispatchComparisonCat{cat_id=id,name=id==a ? "ミケ" : "タマ",status="在店",rows=new[]{new PythonDispatchComparisonRow{kind="general",choice="neighborhood_visit",label="近所のお店",reward=156,days=1,can_select=true,details="近所のお店（一般派遣）\n出発費用：0 / 帰還まで：1回の閉店\n基本報酬：120 × 特性1.3倍 × 得意分野1倍 ＋ 歓迎加算0 ＝ 156\n歓迎条件：なし\n解放状況：最初から利用可能\n現在：派遣できます。"},new PythonDispatchComparisonRow{kind="general",choice="shopping_street_event",label="商店街イベント",reward=250,days=2,reason="未解放：人気150が必要です。",details="商店街イベント（一般派遣）\n出発費用：0 / 帰還まで：2回の閉店\n基本報酬：180 × 特性1倍 × 得意分野1.2倍 ＋ 歓迎加算34 ＝ 250\n歓迎条件：長毛 一致 / 得意分野 派遣 一致\n解放状況：未解放\n現在：人気150が必要です。"},new PythonDispatchComparisonRow{kind="patron",choice="patron_visit",label="有力者訪問",can_select=true,details="有力者訪問\n満足度加点：+20"}}};state.dispatch_comparison=new PythonDispatchComparison{cats=new[]{cat(a),cat(b)},notes="現在の猫と保存設定から比較します。選択イベント・トラブルの報酬変化は含みません。出発は派遣先の画面から行います。"};state.general_dispatch=new PythonPatronDispatch{options=new[]{new PythonDispatchOption{cat_id=a,choice="neighborhood_visit",label="ミケ / 近所",can_select=true},new PythonDispatchOption{cat_id=b,choice="neighborhood_visit",label="タマ / 近所",can_select=true},new PythonDispatchOption{cat_id=b,choice="shopping_street_event",label="タマ / 商店街",reason="未解放"}},events=new PythonDispatchEvent[0]};state.patron_dispatch=new PythonPatronDispatch{options=new[]{new PythonDispatchOption{cat_id=b,choice="patron_visit",label="有力者訪問",can_select=true}},events=new PythonDispatchEvent[0]};Action apply=()=>typeof(PythonStateClient).GetMethod("Accept",f).Invoke(client,new object[]{state});apply();var p=preview.GetComponent<PythonDispatchComparisonPanel>();var list=preview.GetComponent<PythonEventListPanel>();list.Open();if(list.entries.Length!=25 || !list.entries[22].interactable)throw new Exception("Comparison entry missing");list.DispatchComparison();if(list.panel.activeSelf || !p.panel.activeSelf || !p.details.text.Contains("特性1.3倍"))throw new Exception("Comparison navigation failed");Capture(preview,"Logs/DispatchComparison.png");p.cats.onValueChanged.Invoke(1);p.destinations.onValueChanged.Invoke(1);if(!p.title.text.Contains("タマ") || !p.notice.text.Contains("未解放"))throw new Exception("Cat/destination selection failed");if(p.details.GetComponentInParent<ScrollRect>(true).verticalNormalizedPosition>=.99f)throw new Exception("Selected destination did not scroll into view");Capture(preview,"Logs/DispatchComparisonSelected.png");state.revision++;apply();if(p.destinations.value!=1 || p.cats.value!=1)throw new Exception("Comparison selection lost");p.proceed.onClick.Invoke();var general=preview.GetComponent<PythonGeneralDispatchPanel>();if(p.panel.activeSelf || !general.panel.activeSelf || general.destinations.value!=2 || general.send.interactable || typeof(PythonStateClient).GetField("pending",f).GetValue(client)!=null)throw new Exception("General route sent wrong cat or dispatched");general.Close();p.Open();p.SelectDestination(2);p.Proceed();var patron=preview.GetComponent<PythonDispatchPanel>();if(!patron.panel.activeSelf || !patron.send.interactable || !patron.title.text.Contains("タマ"))throw new Exception("Patron route failed");patron.Close();p.Open();p.Disconnect();if(p.proceed.interactable || p.cats.interactable || p.destinations.interactable)throw new Exception("Offline comparison enabled");apply();state.dispatch_comparison.cats[1].rows[0].details=new string('長',4000);apply();Canvas.ForceUpdateCanvases();var scroll=p.details.GetComponentInParent<ScrollRect>(true);if(scroll.content.rect.height<=scroll.viewport.rect.height)throw new Exception("Comparison did not scroll");state.dispatch_comparison.cats=new[]{cat(a)};apply();if(p.cats.value!=0 || !p.title.text.Contains("ミケ"))throw new Exception("Removed cat retained");state.instance_id="loaded";apply();if(p.panel.activeSelf)throw new Exception("New instance retained comparison");p.Open();state.dispatch_comparison.cats=new PythonDispatchComparisonCat[0];apply();if(p.proceed.interactable || p.destinations.interactable || !p.details.text.Contains("ありません"))throw new Exception("Empty comparison enabled");Debug.Log("CAT_CAFE_DISPATCH_COMPARISON_DISPLAY_OK");
        }
        static void Capture(ContentPreview p,string path){Canvas.ForceUpdateCanvases();typeof(ContentPreviewSetup).GetMethod("CaptureCanvas",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).Invoke(null,new object[]{p,path});}
    }
}
